<?php
declare(strict_types=1);$active_module='ical';require_once __DIR__.'/layout.php';require_once __DIR__.'/../config/ical.php';if(empty($_SESSION['supplier_csrf']))$_SESSION['supplier_csrf']=bin2hex(random_bytes(32));$u=$supplier_user;$pdo=db();$message='';$error='';try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['supplier_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Güvenlik doğrulaması geçersiz.');$action=$_POST['action']??'';if($action==='create'){$property=(int)$_POST['property_id'];$direction=$_POST['direction']==='import'?'import':'export';$label=trim((string)$_POST['label']);$url=trim((string)$_POST['source_url']);if(!$property||$label==='')throw new RuntimeException('Ürün ve bağlantı adı zorunludur.');if($direction==='import'&&(!filter_var($url,FILTER_VALIDATE_URL)||!preg_match('/\.ics(?:$|[?#])/i',$url)))throw new RuntimeException('İçe aktarma için .ics ile biten geçerli takvim URL’si gerekir.');$check=$pdo->prepare("SELECT id FROM properties WHERE id=? AND supplier_id=? AND property_type IN ('villa','yacht')");$check->execute([$property,$u['supplier_id']]);if(!$check->fetch())throw new RuntimeException('iCal yalnızca size ait tatil evi veya yat ürünlerine eklenebilir.');$pdo->prepare('INSERT INTO ical_connections(supplier_id,property_id,direction,label,access_token,source_url) VALUES(?,?,?,?,?,?)')->execute([$u['supplier_id'],$property,$direction,$label,bin2hex(random_bytes(32)),$direction==='import'?$url:null]);$message='iCal bağlantısı oluşturuldu.';}if($action==='refresh'){$result=ical_import_connection((int)$_POST['connection_id'],(int)$u['supplier_id']);if(!$result['ok'])throw new RuntimeException($result['message']);$message=$result['message'];}if($action==='pause'){$pdo->prepare("UPDATE ical_connections SET status='paused' WHERE id=? AND supplier_id=?")->execute([(int)$_POST['connection_id'],$u['supplier_id']]);$message='Bağlantı duraklatıldı.';}if($action==='activate'){$pdo->prepare("UPDATE ical_connections SET status='active', last_error=NULL WHERE id=? AND supplier_id=? AND status IN ('paused','error')")->execute([(int)$_POST['connection_id'],$u['supplier_id']]);$message='Bağlantı yeniden etkinleştirildi.';}}}catch(Throwable $e){$error=$e->getMessage();}$q=$pdo->prepare("SELECT id,name,property_type FROM properties WHERE supplier_id=? AND property_type IN ('villa','yacht') ORDER BY name");$q->execute([$u['supplier_id']]);$products=$q->fetchAll();$q=$pdo->prepare('SELECT c.*,p.name property_name,p.status property_status,(SELECT COUNT(*) FROM ical_events e WHERE e.ical_connection_id=c.id) event_count FROM ical_connections c JOIN properties p ON p.id=c.property_id WHERE c.supplier_id=? ORDER BY c.id DESC');$q->execute([$u['supplier_id']]);$connections=$q->fetchAll();$icalUrlPublishedOnly=(bool)platform_setting('ical_url_published_only',false);supply_start('iCal takvim bağlantıları',$active_module);?><section class="page-intro"><p>Tatil evi ve yat ürünleriniz için sınırsız iCal bağlantısı ekleyin. Airbnb, Vrbo, Booking.com ve diğer .ics sağlayıcılarından blokları içe alın; NEXUS takviminizi de her kanal için ayrı URL ile dışa verin.</p></section><?php if($message):?><p class="save-success">✓ <?=htmlspecialchars($message)?></p><?php endif;?><?php if($error):?><p class="login-error"><?=htmlspecialchars($error)?></p><?php endif;?><section class="panel" style="margin-top:34px"><h2 style="margin:0 0 4px">📊 Senkron sağlığı · son 30 gün</h2><p style="margin:0 0 14px;color:#6b7774;font-size:13px">Her ilanın iCal içe/dışa aktarma denemeleri: başarı/hata oranı, ortalama sıklık ve son senkron. <b>Oran</b>: son 30 gündeki başarılı deneme yüzdesi. <b>Sıklık</b>: günde ortalama senkron sayısı (aktif gün sayısıyla birlikte).</p><?php $health=$pdo->query("SELECT p.id,p.name,p.property_type,COUNT(l.id) attempts,COUNT(*) FILTER (WHERE l.status='success') ok,COUNT(*) FILTER (WHERE l.status='failed') fail,COUNT(DISTINCT l.created_at::date) active_days,MAX(l.created_at) last_at FROM properties p JOIN ical_connections c ON c.property_id=p.id LEFT JOIN ical_sync_logs l ON l.ical_connection_id=c.id AND l.created_at>=now()-interval '30 days' WHERE p.supplier_id={$u['supplier_id']} GROUP BY p.id,p.name,p.property_type ORDER BY p.name")->fetchAll();if(!$health):?><p style="color:#6b7774;font-size:13px">Henüz iCal bağlantısı yok — aşağıdan ilk bağlantıyı ekleyin.</p><?php else:?><table style="width:100%;border-collapse:collapse;font-size:13px"><tr><th style="text-align:left;padding:8px 10px;border-bottom:1px solid #d9dfd8;font-size:10px;letter-spacing:.08em;color:#6b7774">İlan</th><th style="text-align:left;padding:8px 10px;border-bottom:1px solid #d9dfd8;font-size:10px;letter-spacing:.08em;color:#6b7774">Deneme</th><th style="text-align:left;padding:8px 10px;border-bottom:1px solid #d9dfd8;font-size:10px;letter-spacing:.08em;color:#6b7774">Başarı / Hata</th><th style="text-align:left;padding:8px 10px;border-bottom:1px solid #d9dfd8;font-size:10px;letter-spacing:.08em;color:#6b7774">Başarı oranı</th><th style="text-align:left;padding:8px 10px;border-bottom:1px solid #d9dfd8;font-size:10px;letter-spacing:.08em;color:#6b7774">Ort. sıklık</th><th style="text-align:left;padding:8px 10px;border-bottom:1px solid #d9dfd8;font-size:10px;letter-spacing:.08em;color:#6b7774">Son senkron</th></tr><?php foreach($health as $h):$attempts=(int)$h['attempts'];$ok=(int)$h['ok'];$fail=(int)$h['fail'];$rate=$attempts>0?round(($ok/$attempts)*100):null;$rateColor=$rate===null?'#8a9aa0':($rate>=80?'#2e7d32':($rate>=50?'#b26a00':'#b0301a'));$freq=$attempts>0?round($attempts/30,1):0;?><tr><td style="padding:8px 10px;border-bottom:1px solid #eef0ea"><b><?=htmlspecialchars($h['name'])?></b> <small style="color:#6b7774">(<?=htmlspecialchars($h['property_type'])?>)</small></td><td style="padding:8px 10px;border-bottom:1px solid #eef0ea"><?=$attempts?></td><td style="padding:8px 10px;border-bottom:1px solid #eef0ea"><?= $ok?('<b style="color:#2e7d32">'.$ok.' ✓</b>'):'0 ✓' ?> · <?= $fail?('<b style="color:#b0301a">'.$fail.' ✗</b>'):'0 ✗' ?></td><td style="padding:8px 10px;border-bottom:1px solid #eef0ea"><span style="display:inline-block;padding:2px 9px;border-radius:12px;background:<?=$rate===null?'#eef0ea':'#eef4ee'?>;color:<?=$rateColor?>;font-weight:700"><?=$rate===null?'—':$rate.'%'?></span></td><td style="padding:8px 10px;border-bottom:1px solid #eef0ea"><?=$attempts>0?('günde ~'.str_replace('.',',',(string)$freq).' · '.$h['active_days'].'/30 gün aktif'):'—'?></td><td style="padding:8px 10px;border-bottom:1px solid #eef0ea"><?php if($h['last_at']):$daysAgo=(int)floor((time()-strtotime((string)$h['last_at']))/86400);?><span <?= $daysAgo>7?'style="color:#b0301a;font-weight:700"':'' ?>><?=htmlspecialchars(date('d.m',strtotime((string)$h['last_at'])))?><?= $daysAgo<=0?' (bugün)':(' ('.$daysAgo.' gün önce)') ?></span><?php else:?><span style="color:#b0301a;font-weight:700">30 günde senkron yok</span><?php endif;?></td></tr><?php endforeach;?></table><?php endif;?></section><section class="next-module"><h2>Yeni iCal bağlantısı</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="create"><div class="form-row"><label>Tatil evi / yat<select name="property_id"><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'].' · '.$p['property_type'])?></option><?php endforeach;?></select></label><label>Bağlantı yönü<select name="direction"><option value="import">Dış takvimi içe aktar</option><option value="export">NEXUS takvimini dışa aktar</option></select></label><label>Bağlantı adı<input name="label" placeholder="Airbnb Ana Takvim" required></label></div><label>Kaynak iCal URL’si <small>(yalnızca içe aktarmada; .ics ile bitmeli)</small><input name="source_url" type="url" placeholder="https://.../calendar.ics"></label><button>iCal bağlantısını oluştur</button></form></section><section class="next-module"><h2>Bağlantılar</h2><?php $syncLogsAll=$pdo->query("SELECT ical_connection_id,status,error_message,created_at FROM ical_sync_logs WHERE ical_connection_id IN (SELECT id FROM ical_connections WHERE supplier_id={$u['supplier_id']}) AND created_at>=now()-interval '7 days' ORDER BY created_at DESC LIMIT 200")->fetchAll();$syncLogsByConn=[];foreach($syncLogsAll as $_sl){$syncLogsByConn[(int)$_sl['ical_connection_id']][]=$_sl;}foreach($connections as $c):$connLogs=$syncLogsByConn[(int)$c['id']]??[];$fail24=0;$lastLog=null;foreach($connLogs as $_cl){if($_cl['status']==='failed'&&strtotime((string)$_cl['created_at'])>=time()-86400)$fail24++;if($lastLog===null)$lastLog=$_cl;}?><article><h3><?=htmlspecialchars($c['property_name'])?> · <?=htmlspecialchars($c['label'])?></h3><p><b><?=htmlspecialchars($c['direction'])?></b> · <?=htmlspecialchars($c['status'])?> · <?= (int)$c['event_count']?> blok · son senkronizasyon <?=htmlspecialchars($c['last_sync_at']??'henüz yok')?><?php if($fail24>0):?><span class="ical-err-badge" title="Son 24 saatte <?=$fail24?> senkron hatası — bağlantıyı kontrol edin">son 24 saatte <?=$fail24?> hata</span><?php endif;?></p><?php if($c['direction']==='export'):$icalFull='https://nexustraveltech.com/api/ical?token='.$c['access_token'];$icalQ='token='.$c['access_token'];$icalShort='api/ical?'.mb_substr($icalQ,0,10).'…'.mb_substr($icalQ,30,4).'…';?><label>NEXUS iCal URL’si<?= $icalUrlPublishedOnly && $c['property_status'] !== 'active' ? ' <em>(yalnızca yayındaki ilanlarda gösterilir)</em>' : '' ?></label><?php if(!$icalUrlPublishedOnly || $c['property_status'] === 'active'): ?><div class="ical-url-box"><span class="ical-url-label" title="<?=htmlspecialchars($icalFull)?>"><?=htmlspecialchars($icalShort)?></span><button type="button" class="ical-copy-btn" data-copy="<?=htmlspecialchars($icalFull)?>">Kopyala</button></div><p>Bu adresi Airbnb/Vrbo/Booking.com kanalındaki “calendar import” alanına yapıştırın.</p><?php else: ?><p class="conn-hint">İlan yayına alınınca bu URL gösterilecek.</p><?php endif; ?><?php else:?><p>Kaynak: <?=htmlspecialchars($c['source_url'])?></p><form method="post" id="ical-sync-<?=$c['id']?>" data-property="<?=(int)$c['property_id']?>" data-ical-sync><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="refresh"><input type="hidden" name="connection_id" value="<?=$c['id']?>"><button>Şimdi içe aktar</button></form><?php $lastSyncTs=$c['last_sync_at']?strtotime((string)$c['last_sync_at']):0;$ageDays=$lastSyncTs>0?floor((time()-$lastSyncTs)/86400):null;?><p class="conn-hint ical-sync-status"><?php if($ageDays!==null):?>son senkron: <b><?= $ageDays<=0 ? 'bugün' : $ageDays.' gün önce' ?></b><?php else:?><b>henüz senkron yok</b><?php endif;?> · son 24 saat: <?=$fail24?> başarısız girişim<?= $lastLog?' · son deneme '.htmlspecialchars((string)$lastLog['created_at']):''?><?= $c['last_error']?' · <span style="color:#b0301a">son hata: '.htmlspecialchars($c['last_error']).'</span>':''?></p><?php endif;?><?php if(!empty($connLogs)):?><details class="ical-sync-log-details" style="margin:10px 0"><summary style="cursor:pointer;padding:6px 0;font-size:13px;color:#374957;font-weight:600">📋 Son senkron günlüğü (<?=count($connLogs)?> kayıt)</summary><table class="ical-sync-log-table" style="width:100%;border-collapse:collapse;font-size:12px"><tr><th style="text-align:left;padding:6px 8px;border-bottom:1px solid #d9dfd8;font-size:10px;letter-spacing:.06em;color:#6b7774">Zaman</th><th style="text-align:left;padding:6px 8px;border-bottom:1px solid #d9dfd8;font-size:10px;letter-spacing:.06em;color:#6b7774">Durum</th><th style="text-align:left;padding:6px 8px;border-bottom:1px solid #d9dfd8;font-size:10px;letter-spacing:.06em;color:#6b7774">Hata</th></tr><?php foreach(array_slice($connLogs,0,10) as $_log):$isErr=$_log['status']==='failed';?><tr><td style="padding:6px 8px;border-bottom:1px solid #eef0ea;white-space:nowrap"><?=htmlspecialchars(date('d.m H:i',strtotime((string)$_log['created_at'])))?></td><td style="padding:6px 8px;border-bottom:1px solid #eef0ea"><?php if($isErr):?><span style="color:#b0301a;font-weight:700">✗ Hata</span><?php else:?><span style="color:#2e7d32;font-weight:700">✓ Başarılı</span><?php endif;?></td><td style="padding:6px 8px;border-bottom:1px solid #eef0ea;max-width:340px;word-break:break-word;color:#5a6b6e"><?php if($_log['error_message']):?><?=htmlspecialchars(mb_substr($_log['error_message'],0,200))?><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></table><?php if(count($connLogs)>10):?><p style="font-size:11px;color:#8a9aa0;margin:4px 0 0">… ve <?=count($connLogs)-10?> daha eski kayıt (son 7 gün)</p><?php endif;?></details><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="pause"><input type="hidden" name="connection_id" value="<?=$c['id']?>"><button>Bağlantıyı duraklat</button></form><?php if($c['status']!=='active'):?><form method="post" style="display:inline;margin-left:8px"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="activate"><input type="hidden" name="connection_id" value="<?=$c['id']?>"><button>↻ Yeniden etkinleştir</button></form><?php endif;?><?= $c['last_error']?'<p class="login-error">'.htmlspecialchars($c['last_error']).'</p>':''?></article><?php endforeach;?></section><script>function fallbackCopy(text){var ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();try{document.execCommand('copy')}catch(e){}document.body.removeChild(ta)}document.querySelectorAll('.ical-copy-btn').forEach(function(b){b.addEventListener('click',function(){var url=this.getAttribute('data-copy'),btn=this;function done(){btn.textContent='Kopyalandı ✓';btn.classList.add('copied');setTimeout(function(){btn.textContent='Kopyala';btn.classList.remove('copied')},1600)}if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(url).then(done).catch(function(){fallbackCopy(url);done()})}else{fallbackCopy(url);done()}})});</script><script>(function(){if(!location.hash||location.hash.indexOf('#sync')!==0)return;var params=new URLSearchParams(location.search),prop=parseInt(params.get('property')||'0',10),target=null;if(location.hash.length>5){target=document.getElementById(location.hash.slice(1))}if(!target&&prop>0){target=document.querySelector('form[data-ical-sync][data-property="'+prop+'"]')}if(!target){target=document.querySelector('form[data-ical-sync]')}if(target){setTimeout(function(){var y=target.getBoundingClientRect().top+window.scrollY-110;window.scrollTo({top:y,behavior:'smooth'});var btn=target.querySelector('button');if(btn){btn.focus({preventScroll:true});btn.classList.add('ical-sync-flash');setTimeout(function(){btn.classList.remove('ical-sync-flash')},2200)}},80)}})();</script><?php supply_end();
